{
  "microservices": [
    {
      "microservice_name": "Master Data Service",
      "responsibility": "Maintain supporting master data such as departments, contract types, user categories, organization types, interaction types, tax reasons, billing schemes, and frequencies.",
      "communicates_with": [
        "User Management Service",
        "CRM Service",
        "Finance and Billing Service",
        "Project Management Service"
      ]
    },
    {
      "microservice_name": "User Management Service",
      "responsibility": "Manage users, access profiles, employment agreements, password management, and personal settings.",
      "communicates_with": [
        "Master Data Service",
        "Security and Access Control Service",
        "Vacation Management Service",
        "Document Management Service"
      ]
    },
    {
      "microservice_name": "Security and Access Control Service",
      "responsibility": "Enforce access control by user profile and scope, support local and LDAP authentication, and apply security to critical entities.",
      "communicates_with": [
        "User Management Service",
        "Document Management Service",
        "Finance and Billing Service",
        "CRM Service",
        "Project Management Service",
        "Activity and Time Reporting Service",
        "Order and Commission Service"
      ]
    },
    {
      "microservice_name": "Vacation Management Service",
      "responsibility": "Record and manage vacation requests, calculate balances, control lifecycle, and notify approvers.",
      "communicates_with": [
        "User Management Service",
        "Notification Service"
      ]
    },
    {
      "microservice_name": "CRM Service",
      "responsibility": "Manage organizations, contacts, external collaborators, job roles, interaction types, interactions, and proposals including lifecycle, composition, duplication, and conversion to billing.",
      "communicates_with": [
        "Master Data Service",
        "Project Management Service",
        "Finance and Billing Service",
        "Security and Access Control Service"
      ]
    },
    {
      "microservice_name": "Project Management Service",
      "responsibility": "Register and maintain projects associated with clients, including active period, status, involved roles, and related costs.",
      "communicates_with": [
        "Master Data Service",
        "CRM Service",
        "Activity and Time Reporting Service",
        "Finance and Billing Service"
      ]
    },
    {
      "microservice_name": "Activity and Time Reporting Service",
      "responsibility": "Record internal and external activities, classify billable/non-billable, distinguish workday time, maintain objectives and allocations, produce consolidated reports, and manage evidence with policies and alerts.",
      "communicates_with": [
        "Project Management Service",
        "User Management Service",
        "Notification Service",
        "Finance and Billing Service"
      ]
    },
    {
      "microservice_name": "Finance and Billing Service",
      "responsibility": "Maintain accounts, transaction types/groups, recurring transactions; record receivables/payables; detail billing records; calculate totals, withholdings, outstanding balances, and paid status; manage due dates and credit instruments; import billable hours and project costs; track financial indicators.",
      "communicates_with": [
        "Master Data Service",
        "CRM Service",
        "Project Management Service",
        "Activity and Time Reporting Service",
        "Order and Commission Service",
        "Security and Access Control Service"
      ]
    },
    {
      "microservice_name": "Document Management Service",
      "responsibility": "Organize documents by category, maintain versions, associate with responsible people and areas, auto-create per-user document categories, and maintain publications, notice boards, and other supporting content.",
      "communicates_with": [
        "User Management Service",
        "Security and Access Control Service"
      ]
    },
    {
      "microservice_name": "Order and Commission Service",
      "responsibility": "Record orders and commissions linked to projects, reviewers, collaborators, and payment data; control workflow states; record delays, changes, and files; preserve textual history; send documents by email.",
      "communicates_with": [
        "Project Management Service",
        "Finance and Billing Service",
        "Notification Service"
      ]
    },
    {
      "microservice_name": "Notification Service",
      "responsibility": "Send email notifications for relevant business events such as vacation requests, contract expiry, password reset, pending evidence, and orders.",
      "communicates_with": [
        "Vacation Management Service",
        "User Management Service",
        "Activity and Time Reporting Service",
        "Order and Commission Service"
      ]
    },
    {
      "microservice_name": "Reporting Service",
      "responsibility": "Provide reports by business domain and export in multiple formats including CSV, PDF, HTML, RTF, XLS, and ODT.",
      "communicates_with": [
        "Finance and Billing Service",
        "Activity and Time Reporting Service",
        "CRM Service",
        "Project Management Service",
        "Order and Commission Service"
      ]
    }
  ]
}
